def write_all(dirpath: str) -> Dict[str, int]:
    import os
    out = {}
    with open(os.path.join(dirpath, "proposed_experiments.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=list(EXPERIMENTS[0].keys()))
        w.writeheader()
        for r in EXPERIMENTS:
            w.writerow(r)
    out["experiments"] = len(EXPERIMENTS)
    with open(os.path.join(dirpath, "proposed_criteria.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=CRIT_COLUMNS)
        w.writeheader()
        for r in CRITERIA:
            w.writerow({c: r.get(c, "") for c in CRIT_COLUMNS})
    out["criteria"] = len(CRITERIA)
    with open(os.path.join(dirpath, "experiment_merge_map.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=["existing", "rig", "relation", "note"])
        w.writeheader()
        for r in MERGE_MAP:
            w.writerow(r)
    out["merge_rows"] = len(MERGE_MAP)
    return out
